"""
Automated content scanning for uploaded distribution files.

This module wraps ``yara-x`` to scan the contents of uploaded archives for
known-bad patterns (for example, PyArmor-encrypted payloads). The scanning is
intentionally *fail-open*: any error encountered while compiling rules or
scanning content results in the content being treated as clean, so that a
problem with the scanner can never block a legitimate upload.
"""

import os
import tarfile
import zipfile

from dataclasses import dataclass
from typing import Optional

import yara_x

# The directory containing the built-in ``*.yar`` rule files.
_RULES_DIR = os.path.join(os.path.dirname(__file__), "scanner_rules")

# Maximum size (in bytes) of a single archive member that we will scan. Members
# larger than this are silently skipped. Patchable in tests.
_SCAN_MAX_FILE_SIZE = 32 * 1024 * 1024

# When the accumulated size of the members handed to :func:`check_members`
# exceeds this threshold we stop bulk scanning and fall back to per-file
# scanning for the remaining members. Patchable in tests.
_BULK_SCAN_MAX_TOTAL = 64 * 1024 * 1024

# The file extensions we consider "Python files" worth scanning.
_PYTHON_EXTENSIONS = (".py", ".pyc", ".pyd", ".so")


@dataclass(frozen=True)
class YaraMatch:
    """A single YARA rule match found while scanning an archive."""

    rule: str
    member: str
    message: str


def compile_rules(rules_dir=None) -> Optional[yara_x.Rules]:
    """
    Compile all ``*.yar`` files found in ``rules_dir``.

    Defaults to the built-in ``scanner_rules`` directory. Returns ``None`` if no
    ``.yar`` files are found, if any rule file fails to compile, or if any other
    error occurs (fail-open).
    """
    if rules_dir is None:
        rules_dir = _RULES_DIR

    try:
        rule_files = sorted(
            os.path.join(rules_dir, name)
            for name in os.listdir(rules_dir)
            if name.endswith(".yar")
        )

        if not rule_files:
            return None

        compiler = yara_x.Compiler()
        for rule_file in rule_files:
            with open(rule_file, encoding="utf-8") as fp:
                compiler.add_source(fp.read(), origin=rule_file)

        return compiler.build()
    except Exception:
        # Fail-open: never let a scanner problem block an upload.
        return None


def _get_rule_message(rule) -> str:
    """Return the ``message`` metadata value from a matched YARA rule."""
    for key, value in rule.metadata:
        if key == "message":
            return value
    return ""


# The compiled built-in rules, or ``None`` if they could not be compiled.
# Patchable in tests.
_rules = compile_rules()


def _match_from_rule(rule, member) -> YaraMatch:
    return YaraMatch(
        rule=rule.identifier,
        member=member,
        message=_get_rule_message(rule),
    )


def check_members(members, rules=None, *, archive_name="") -> Optional[YaraMatch]:
    """
    Scan an iterable of archive members for YARA rule matches.

    Each member is a ``(path_str, size, data)`` tuple. Members larger than
    :data:`_SCAN_MAX_FILE_SIZE` are skipped. Returns a :class:`YaraMatch` for the
    first matching member, or ``None`` if nothing matches.

    To reduce per-scan overhead, members are scanned in bulk (concatenated)
    until their accumulated size exceeds :data:`_BULK_SCAN_MAX_TOTAL`, after
    which the remaining members are scanned one at a time. Because a bulk scan
    can produce a spurious match spanning the boundary between two members, any
    bulk match is confirmed by re-scanning the individual members; if no
    individual member confirms the match it is discarded (fail-open).

    Returns ``None`` on :class:`yara_x.ScanError` (fail-open).
    """
    if rules is None:
        rules = _rules
    if rules is None:
        return None

    scanner = yara_x.Scanner(rules)

    def scan_one(path_str, data):
        matching = scanner.scan(data).matching_rules
        if matching:
            return _match_from_rule(matching[0], path_str)
        return None

    def flush_bulk(chunks):
        # Bulk-scan the accumulated chunks, then confirm any match against the
        # individual members to avoid cross-boundary false positives.
        if not chunks:
            return None
        buffer = b"".join(data for _, data in chunks)
        if not scanner.scan(buffer).matching_rules:
            return None
        for path_str, data in chunks:
            match = scan_one(path_str, data)
            if match is not None:
                return match
        return None

    bulk_chunks = []
    total = 0
    per_file_mode = False

    try:
        for path_str, size, data in members:
            if size > _SCAN_MAX_FILE_SIZE:
                continue

            total += size
            if not per_file_mode and total > _BULK_SCAN_MAX_TOTAL:
                match = flush_bulk(bulk_chunks)
                if match is not None:
                    return match
                bulk_chunks = []
                per_file_mode = True

            if per_file_mode:
                match = scan_one(path_str, data)
                if match is not None:
                    return match
            else:
                bulk_chunks.append((path_str, data))

        return flush_bulk(bulk_chunks)
    except yara_x.ScanError:
        return None


def scan_archive(path, rules=None) -> list[tuple[str, list[str]]]:
    """
    Scan every Python file in the archive at ``path`` for YARA rule matches.

    Supports ``.whl``/``.zip`` and ``.tar.gz`` archives. Returns a list of
    ``(member_path, [rule_identifiers])`` tuples for each matching Python file.
    Only files with an extension in :data:`_PYTHON_EXTENSIONS` are scanned;
    directory entries, non-file tar members, and oversized files are skipped.
    Returns ``[]`` for unsupported formats, corrupt archives, or when no rules
    are available.
    """
    if rules is None:
        rules = _rules
    if rules is None:
        return []

    scanner = yara_x.Scanner(rules)
    results: list[tuple[str, list[str]]] = []

    def scan_data(member_path, data):
        try:
            matching = scanner.scan(data).matching_rules
        except yara_x.ScanError:
            return
        if matching:
            results.append((member_path, [rule.identifier for rule in matching]))

    try:
        if path.endswith((".whl", ".zip")):
            with zipfile.ZipFile(path) as zfp:
                for info in zfp.infolist():
                    if info.is_dir():
                        continue
                    if not info.filename.endswith(_PYTHON_EXTENSIONS):
                        continue
                    if info.file_size > _SCAN_MAX_FILE_SIZE:
                        continue
                    scan_data(info.filename, zfp.read(info))
        elif path.endswith(".tar.gz"):
            with tarfile.open(path, "r:gz") as tar:
                for member in tar:
                    if not member.isfile():
                        continue
                    if not member.name.endswith(_PYTHON_EXTENSIONS):
                        continue
                    if member.size > _SCAN_MAX_FILE_SIZE:
                        continue
                    extracted = tar.extractfile(member)
                    if extracted is None:
                        continue
                    scan_data(member.name, extracted.read())

